import re
import datetime

def add_business_days(start, n, holidays):
    # Validate start format
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', start):
        raise ValueError(f"Invalid start date format: {start}")
    try:
        start_date = datetime.datetime.strptime(start, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError(f"Invalid start date: {start}")
    # Validate n
    if type(n) is not int or n < 0:
        raise ValueError("n must be a non-negative integer")
    # Validate holidays
    holiday_set = set()
    for h in holidays:
        if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', h):
            raise ValueError(f"Invalid holiday date format: {h}")
        try:
            hd = datetime.datetime.strptime(h, "%Y-%m-%d").date()
            holiday_set.add(hd)
        except ValueError:
            raise ValueError(f"Invalid holiday date: {h}")
    # If n == 0, return start unchanged
    if n == 0:
        return start
    # Iterate forward
    current = start_date + datetime.timedelta(days=1)
    count = 0
    while count < n:
        if current.weekday() < 5 and current not in holiday_set:
            count += 1
        current += datetime.timedelta(days=1)
    return current.strftime("%Y-%m-%d")

